/// <summary>
/// CB129 Cancellation of Open SO/PO lines
/// </summary>
internal final class METPurchLineOpenOrderEvents
{
}

Method.Source:
/// <summary>
/// Event to change the query based on selection
/// </summary>
/// <param name = "sender">sender</param>
/// <param name = "e">e</param>
[FormControlEventHandler(formControlStr(PurchLineOpenOrder, METIgnoreDeliveryCheckBoxControl), FormControlEventType::Clicked), SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void METIgnoreDeliveryCheckBoxControl_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun              formRun = sender.formRun();
    FormDataSource       fds = formRun.dataSource(formdatasourcestr(PurchLineOpenOrder, PurchLine));
    QueryBuildDataSource qbds;
    FormCheckBoxControl  formceckboxcontrol = sender;
    QueryBuildDataSource qbdsInventTrans;

    if (formceckboxcontrol.checked())
    {
        qbds = fds.query().dataSourceTable(tableNum(InventTransOrigin));
        if(!qbds)
        {
            qbds = fds.queryBuildDataSource().addDataSource(tableNum(InventTransOrigin));
            qbds.addLink(fieldNum(PurchLine, InventTransId),fieldNum(InventTransOrigin, InventTransId));
            qbds.joinMode(JoinMode::NoExistsJoin);
            qbds.relations(false);
            qbdsInventTrans = qbds.addDataSource(tableNum(InventTrans));
            qbdsInventTrans.addLink(fieldNum(InventTrans, InventTransOrigin),fieldNum(InventTransOrigin, RecId));
            qbdsInventTrans.joinMode(JoinMode::ExistsJoin);
            qbdsInventTrans.relations(false);

            qbdsInventTrans.addRange(fieldNum(InventTrans, StatusReceipt)).value(queryValue(StatusReceipt::Received));
            qbdsInventTrans.addRange(fieldNum(InventTrans, StatusReceipt)).value(queryValue(StatusReceipt::Registered));
        }
        fds.query().dataSourceTable(tableNum(InventTransOrigin)).enabled(true);
        fds.query().dataSourceTable(tableNum(InventTrans)).enabled(true);
    }
    else
    {
        qbds = fds.query().dataSourceTable(tableNum(InventTransOrigin));
        qbdsInventTrans = fds.query().dataSourceTable(tableNum(InventTrans));

        if(qbds)
        {
            qbds.clearRanges();
            qbds.relations(false);
            fds.query().dataSourceTable(tableNum(InventTransOrigin)).enabled(False);
            if(qbdsInventTrans)
            {
                qbdsinventtrans.relations(false);
                fds.query().dataSourceTable(tableNum(InventTrans)).enabled(False);
            }
        }
    }
    fds.executeQuery();
}
